#include <vector>
#include <algorithm>
#include <utility>

std::pair<int, float> bucket_partition_point(const std::vector<float>& hash_points, float x) {
    if (hash_points.empty()) {
        return {0, 0.0f};
    }

    auto it = std::upper_bound(hash_points.begin(), hash_points.end(), x);

    if (it == hash_points.end()) {
        // x exceeds all points, wrap to first element
        return {0, hash_points[0]};
    } else {
        // Found partition point immediately greater than x
        int index = static_cast<int>(it - hash_points.begin());
        return {index, *it};
    }
}

// Test cases
