    std::vector<float> points = {1.0f, 2.5f, 4.0f, 7.0f, 10.0f};

    // Test 1: x = 0.0 (should return first element)
    auto result1 = bucket_partition_point(points, 0.0f);

    // Test 2: x = 2.5 (should return 4.0 at index 2)
    auto result2 = bucket_partition_point(points, 2.5f);

    // Test 3: x = 5.0 (should return 7.0 at index 3)
    auto result3 = bucket_partition_point(points, 5.0f);

    // Test 4: x = 15.0 (should wrap to first element)
    auto result4 = bucket_partition_point(points, 15.0f);

    return 0;
}

